from __future__ import absolute_import
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import StaleElementReferenceException
from taf.selenium.sbts.common.exceptions import UnexpectedElementState
from taf.selenium.sbts.pages import v25r1, v25r3
from taf.selenium.sbts.pages.v25r1.modals import BlockCellModal


class BtsStatus(v25r3.BtsStatus):

    def __init__(self, driver):
        super(BtsStatus, self).__init__(driver)
        self._cells = CellsPage(driver)
        self._site_view = SiteViewPage(driver)


class SiteViewPage(v25r3.bts_status.SiteViewPage):

    _NRPOSCELL_XPATH = "//div[contains(@class, 'cell-nrpos-grid-element')]//div[text()='{}']"

    def __init__(self, driver):
        super(SiteViewPage, self).__init__(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)

    def block_nrposcell(self, cell_id, timeout=60):
        cell_xpath = self._get_nrposcell_xpath_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.block_nrposcell(timeout)

    def unblock_nrposcell(self, cell_id, timeout=60):
        cell_xpath = self._get_nrposcell_xpath_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.unblock_nrposcell(timeout)

    def _get_nrposcell_xpath_by_id(self, cell_id):
        return self._NRPOSCELL_XPATH.format(cell_id)


class SiteViewPageDetailPanel(v25r3.bts_status.SiteViewPageDetailPanel):

    _NRPOSCELL_LOCK_STATUS = "Block Cell"
    _NRPOSCELL_UNLOCK_STATUS = "Unblock Cell"

    _NRPOSCELL_LOCK_STATE = "Block"
    _NRPOSCELL_UNLOCK_STATE = "Unblock"

    def block_nrposcell(self, timeout):
        if self._NRPOSCELL_UNLOCK_STATUS == self.get_text_by_xpath(self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is blocked, no need to block")

        self.click_enabled_element_after_visible((By.XPATH, self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_nrposcell_status_on_modal(self._NRPOSCELL_LOCK_STATE, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._AVAILABILITY_STATE_XPATH), 'Blocked', timeout)

    def unblock_nrposcell(self, timeout):
        if self._NRPOSCELL_LOCK_STATUS == self.get_text_by_xpath(self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is unblocked, no need to unblock")

        self.click_enabled_element_after_visible((By.XPATH, self._CELL_GROUP_LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_nrposcell_status_on_modal(self._NRPOSCELL_UNLOCK_STATE, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._AVAILABILITY_STATE_XPATH), 'Unblocked', timeout)

    def _change_nrposcell_status_on_modal(self, state, timeout=60):
        cell_modal = BlockCellModal(self.driver)
        cell_modal.wait_until_block_cell_modal_appear(timeout)
        if state == self._NRPOSCELL_LOCK_STATE:
            cell_modal.block(timeout)
        elif state == self._NRPOSCELL_UNLOCK_STATE:
            cell_modal.unblock(timeout)


class CellsPage(v25r1.bts_status.CellsPage):

    _NRPOSCELLS_XPATH = "//div[contains(@class,'cell-element-root')]//span[text()='NRPOSCELL-{}']"
    _NR_CELL_ID = 'NR cell ID'
    _E_UTRAN_CELL_ID = "E-UTRAN cell ID"
    _CELL_OBJECT_NAME = '//div[@class="header"]//span[contains(@class, "object-name-long")]'

    def __init__(self, driver):
        super(CellsPage, self).__init__(driver)
        self._detail_panel = CellsPageDetailPanel(driver)

    def lock_nrposcell(self, cell_id, timeout=60):
        cell_xpath = self._get_nrposcell_xpath_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.lock_nrposcell(timeout)

    def unlock_nrposcell(self, cell_id, timeout=60):
        cell_xpath = self._get_nrposcell_xpath_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.unlock_nrposcell(timeout)

    def reset_nrposcell(self, cell_id, with_graceful=False, timeout=60):
        cell_xpath = self._get_nrposcell_xpath_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.reset_nrposcell(with_graceful, timeout)

    def _get_nrposcell_xpath_by_id(self, cell_id):
        return self._NRPOSCELLS_XPATH.format(cell_id)

    def _get_cell_xpath_and_info_by_id(self, cell_id, cell_name=None):
        cell_xpath_list = self._view_panel.get_cell_xpath_list(timeout=60)
        logging.info("start to find cell by id: '{}', cell name: '{}'".format(cell_id, cell_name))
        for cell_xpath in cell_xpath_list:
            cell_info = self._get_cell_info_by_xpath(cell_xpath)
            cell_object_name = self._get_cell_object_name().split("(")[0].strip()
            if not cell_name:
                if cell_id == int(cell_info.get(self._GLOBAL_CELL_ID)
                                or cell_info.get(self._CELL_ID)
                                or cell_info.get(self._GSM_SECTOR_ID)):
                    logging.info("found cell by cell id: {}".format(cell_id))
                    return cell_xpath, cell_info

                nr_cell_id = cell_info.get(self._NR_CELL_ID, None)
                if nr_cell_id and int(cell_id) == int(nr_cell_id):
                    logging.info("found cell by NR cell id: {}".format(cell_id))
                    return cell_xpath, cell_info

                lte_cell_id = cell_info.get(self._E_UTRAN_CELL_ID, None)
                if lte_cell_id and int(cell_id) == int(lte_cell_id):
                    logging.info("found cell by E-UTRAN cell id: {}".format(cell_id))
                    return cell_xpath, cell_info

            if cell_name and cell_name.strip().lower() == cell_object_name.lower():
                logging.info("found cell by name: {}".format(cell_name))
                return cell_xpath, cell_info
        raise ValueError("Cannot find cell with id: '{}', name: '{}'".format(cell_id, cell_name))

    def _get_cell_object_name(self, timeout=60):
        return self._view_panel.get_text_by_xpath(self._CELL_OBJECT_NAME, timeout)

    def reset_cell(self, cell_id, with_graceful=False, timeout=60, **kwargs):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id,
                                                            cell_name=kwargs.get('cell_name', None))
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.reset_cell(with_graceful, timeout, **kwargs)


class CellsPageDetailPanel(v25r1.bts_status.CellsPageDetailPanel):

    _NRPOSCELL_LOCK_STATUS = "Block Cell"
    _NRPOSCELL_UNLOCK_STATUS = "Unblock Cell"

    _NRPOSCELL_LOCK_STATE = "Block"
    _NRPOSCELL_UNLOCK_STATE = "Unblock"

    def lock_nrposcell(self, timeout):
        if self._NRPOSCELL_UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is locked, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_nrposcell_status_on_modal(self._NRPOSCELL_LOCK_STATE, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Blocked', timeout)

    def unlock_nrposcell(self, timeout):
        if self._NRPOSCELL_LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_nrposcell_status_on_modal(self._NRPOSCELL_UNLOCK_STATE, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Unblocked', timeout)

    def reset_nrposcell(self, with_graceful=False, timeout=60):
        self.click_enabled_element_after_visible((By.XPATH, self._RESET_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._RESET_STATUS, with_graceful, timeout)
        try:
            self.wait_for_text_present_in_attribute(self._RESET_BUTTON_XPATH, 'a-title', 'Operation ongoing', timeout)
            self.wait_for_text_not_present_in_attribute(self._RESET_BUTTON_XPATH, 'a-title', 'Operation ongoing', timeout)
        except StaleElementReferenceException:
            logging.info("ingnore here, because the element will be invalid after long time waiting")

        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout)

    def _change_nrposcell_status_on_modal(self, state, timeout=60):
        cell_modal = BlockCellModal(self.driver)
        cell_modal.wait_until_block_cell_modal_appear(timeout)
        if state == self._NRPOSCELL_LOCK_STATE:
            cell_modal.block(timeout)
        elif state == self._NRPOSCELL_UNLOCK_STATE:
            cell_modal.unblock(timeout)
